class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If s2 contains characters not present in s1, impossible to match
        if not set(s2).issubset(set(s1)):
            return 0
        # recall maps current index in s2 after a block to (blocks processed, s2 matches)
        recall = {}
        s1_cnt = 0          # number of s1 blocks processed
        s2_cnt = 0          # number of complete s2 matches
        idx = 0             # current position inside s2
        while s1_cnt < n1:
            s1_cnt += 1
            for ch in s1:
                if ch == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        s2_cnt += 1
                        idx = 0
            if idx in recall:
                pre_s1_cnt, pre_s2_cnt = recall[idx]
                pre_cycle_len = s1_cnt - pre_s1_cnt          # blocks per cycle
                pre_cycle_s2_cnt = s2_cnt - pre_s2_cnt       # s2 matches per cycle
                remaining_blocks = n1 - s1_cnt
                cycles = remaining_blocks // pre_cycle_len
                s2_cnt += cycles * pre_cycle_s2_cnt
                s1_cnt += cycles * pre_cycle_len
            else:
                recall[idx] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

