from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        mem = defaultdict(int)

        def dfs(i: int, val: int) -> int:
            if i == len(s):
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            total = 0
            if s[i] == 'D':
                for ind in range(0, val + 1):
                    total = (total + dfs(i + 1, ind)) % MOD
            else:  # 'I'
                for ind in range(val + 1, i + 2):
                    total = (total + dfs(i + 1, ind)) % MOD
            mem[(i, val)] = total
            return total

        return dfs(0, 0)

