class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        q, ans = [root], []
        while q:
            level_size = len(q)
            level_vals = []
            for _ in range(level_size):
                node = q.pop(0)
                level_vals.append(node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            ans.append(level_vals)
        # Reverse the list of levels to achieve bottom‑up order
        return ans[::-1]

