from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # Compute 2D prefix sum for apples
        psum = [[0] * (self.c + 1) for _ in range(self.r + 1)]
        for i in range(1, self.r + 1):
            for j in range(1, self.c + 1):
                psum[i][j] = psum[i-1][j] + psum[i][j-1] - psum[i-1][j-1] + (1 if pizza[i-1][j-1] == 'A' else 0)

        # Helper function to get apples in rectangle from (i,j) to (x,y) inclusive
        def apples_in(i, j, x, y):
            if i > x or j > y:
                return 0
            return psum[x+1][y+1] - psum[i][y+1] - psum[x+1][j] + psum[i][j]

        # If no apples, return 0
        if apples_in(0, 0, self.r-1, self.c-1) == 0:
            return 0

        if k == 1:
            return 1

        @lru_cache(None)
        def getWays(i, j, k):
            if apples_in(i, j, self.r-1, self.c-1) == 0:
                return 0
            if k == 1:
                return 1
            total = 0
            # Horizontal cuts: cut after row r, for r from i to self.r-2
            for nr in range(i, self.r - 1):
                if apples_in(i, j, nr, self.c-1) > 0:
                    total += getWays(nr + 1, j, k - 1)
            # Vertical cuts: cut after column c, for c from j to self.c-2
            for nc in range(j, self.c - 1):
                if apples_in(i, j, self.r-1, nc) > 0:
                    total += getWays(i, nc + 1, k - 1)
            return total % (1000000007)

        return getWays(0, 0, k) % (1000000007)

