from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        rows = len(pizza)
        cols = len(pizza[0]) if rows else 0
        MOD = 1_000_000_007

        # Prefix sum of apples: pref[i][j] = # apples in rectangle (0,0)-(i-1,j-1)
        pref = [[0] * (cols + 1) for _ in range(rows + 1)]
        for i in range(rows):
            row_sum = 0
            for j in range(cols):
                if pizza[i][j] == 'A':
                    row_sum += 1
                pref[i + 1][j + 1] = pref[i][j + 1] + row_sum

        total_apples = pref[rows][cols]
        if total_apples < k:
            return 0

        def hasApple(r1: int, c1: int, r2: int, c2: int) -> bool:
            """Return True if the sub‑rectangle (r1..r2, c1..c2) contains at least one apple."""
            return (pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] -
                    pref[r2 + 1][c1] + pref[r1][c1]) > 0

        @lru_cache(None)
        def dfs(i: int, j: int, pieces: int) -> int:
            if pieces == 1:
                return 1 if hasApple(i, j, rows - 1, cols - 1) else 0
            ans = 0
            # Horizontal cuts
            for r in range(i, rows - 1):
                if hasApple(i, j, r, cols - 1) and hasApple(r + 1, j, rows - 1, cols - 1):
                    ans += dfs(r + 1, j, pieces - 1)
            # Vertical cuts
            for c in range(j, cols - 1):
                if hasApple(i, j, rows - 1, c) and hasApple(i, c + 1, rows - 1, cols - 1):
                    ans += dfs(i, c + 1, pieces - 1)
            return ans % MOD

        return dfs(0, 0, k) % MOD

