class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        dp = [1]  # dp for the first element (rank 0)
        for i, c in enumerate(s):
            new_len = i + 2
            new_dp = [0] * new_len
            if c == 'I':
                # prefix sums: new_dp[j] = sum_{k<j} dp[k]
                prefix = 0
                for j in range(new_len):
                    new_dp[j] = prefix
                    if j < len(dp):
                        prefix = (prefix + dp[j]) % MOD
            else:  # c == 'D'
                # suffix sums: new_dp[j] = sum_{k>=j} dp[k]
                suffix = 0
                for j in range(new_len - 1, -1, -1):
                    if j <= i:
                        suffix = (suffix + dp[j]) % MOD
                    new_dp[j] = suffix
            dp = new_dp
        return sum(dp) % MOD

