from collections import deque

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build Aho‑Corasick automaton for forbidden patterns
        nodes = [{"children": {}, "fail": 0, "out": []}]  # root = 0
        for f in forbidden:
            cur = 0
            for ch in f:
                nxt = nodes[cur]["children"].get(ch)
                if nxt is None:
                    nxt = len(nodes)
                    nodes.append({"children": {}, "fail": 0, "out": []})
                    nodes[cur]["children"][ch] = nxt
                cur = nxt
            nodes[cur]["out"].append(len(f))
        # Build failure links
        q = deque()
        for ch, nxt in nodes[0]["children"].items():
            nodes[nxt]["fail"] = 0
            q.append(nxt)
        while q:
            r = q.popleft()
            for ch, child in nodes[r]["children"].items():
                f = nodes[r]["fail"]
                while f and ch not in nodes[f]["children"]:
                    f = nodes[f]["fail"]
                nodes[child]["fail"] = nodes[f]["children"].get(ch, 0)
                nodes[child]["out"].extend(nodes[nodes[child]["fail"]]["out"])
                q.append(child)

        n = len(word)
        blocked = [0] * n   # for each position i, maximal left bound after a match ending at i
        state = 0
        for i, ch in enumerate(word):
            while state and ch not in nodes[state]["children"]:
                state = nodes[state]["fail"]
            state = nodes[state]["children"].get(ch, 0)
            for length in nodes[state]["out"]:
                left = i - length + 2   # start+1
                if left > blocked[i]:
                    blocked[i] = left

        left = 0
        ans = 0
        for i in range(n):
            if blocked[i] > left:
                left = blocked[i]
            cur_len = i - left + 1
            if cur_len > ans:
                ans = cur_len
        return ans

