from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping can be used at most twice
        toppingCosts = toppingCosts * 2

        @cache
        def dfs(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] closest to x."""
            if i == len(toppingCosts):
                return 0
            if x < 0:
                return 0
            # skip current topping
            skip = dfs(i + 1, x)
            # take current topping
            take = toppingCosts[i] + dfs(i + 1, x - toppingCosts[i])
            return min(skip, take, key=lambda y: (abs(y - x), y))

        best = float('inf')
        for bc in baseCosts:
            cost = bc + dfs(0, target - bc)
            if abs(cost - target) < abs(best - target) or (abs(cost - target) == abs(best - target) and cost < best):
                best = cost
        return best

