from collections import defaultdict, deque
from typing import List

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        # Build ingredient -> recipes graph
        graph = defaultdict(list)   # ingredient -> list of recipes that need it
        indegree = defaultdict(int) # recipe -> number of remaining ingredients needed

        # Initialise graph and indegree counts
        for r, ing in zip(recipes, ingredients):
            indegree[r] = len(ing)
            for i in ing:
                graph[i].append(r)

        queue = deque()
        result = []

        # Add all given supplies as starting nodes
        for s in supplies:
            queue.append(s)

        # Add recipes that need no ingredients (ready immediately)
        for r, ing in zip(recipes, ingredients):
            if len(ing) == 0:
                result.append(r)
                queue.append(r)

        # BFS: each time a node becomes available, reduce indegree of dependent recipes
        while queue:
            cur = queue.popleft()
            for recipe in graph.get(cur, []):
                indegree[recipe] -= 1
                if indegree[recipe] == 0:
                    result.append(recipe)
                    queue.append(recipe)

        return result

