from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        memo = defaultdict(int)
        def dfs(i, val=0):
            if i == len(s):
                return 1
            if (i, val) in memo:
                return memo[(i, val)]
            total = 0
            if s[i] == "D":
                for ind in range(0, val):
                    total += dfs(i+1, ind)
            else:  # s[i] == "I"
                for ind in range(val+1, i+2):
                    total += dfs(i+1, ind)
            memo[(i, val)] = total % MOD
            return memo[(i, val)]
        return dfs(0) % MOD

