class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # generate all possible sums from toppings, each can be used 0, 1 or 2 times
        possible = {0}
        for t in toppingCosts:
            new_sums = set()
            for s in possible:
                new_sums.add(s)          # none
                new_sums.add(s + t)       # one copy
                new_sums.add(s + 2 * t)   # two copies
            possible.update(new_sums)

        best = None
        best_diff = float('inf')
        for bc in baseCosts:
            for s in possible:
                total = bc + s
                diff = abs(total - target)
                if diff < best_diff or (diff == best_diff and total < best):
                    best = total
                    best_diff = diff
        return best

