class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        """Return the k‑th smallest number in the range [1, n] in lexicographic order."""
        def count_prefix(x: int) -> int:
            """Count how many numbers start with prefix x in [1, n]."""
            cnt, step = 0, 1
            while x <= n:
                cnt += min(n - x + 1, step)
                x *= 10
                step *= 10
            return cnt

        cur = 1
        k -= 1  # the first number (cur) has been counted
        while k > 0:
            steps = count_prefix(cur)
            if steps <= k:
                k -= steps
                cur += 1
            else:
                k -= 1
                cur *= 10
        return cur

