    def moveStonesII(self, stones: List[int]) -> List[int]:
        stones.sort()
        n = len(stones)
        if n == 1:
            return [0,0]
        move1 = stones[-2] - stones[0] - (n-2)
        move2 = stones[-1] - stones[1] - (n-2)
        max_moves = max(move1, move2, 0)
        min_moves = n
