class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int)  # net outdegree - indegree

        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        # Find a start node with outdegree - indegree = 1
        start = None
        for k in degree:
            if degree[k] == 1:
                start = k
                break
        # Fallback: any node that appears in pairs
        if start is None:
            start = pairs[0][0] if pairs else None

        ans = []

        def dfs(u: int) -> None:
            while graph[u]:
                v = graph[u].pop()
                dfs(v)
            ans.append(u)

        if start is not None:
            dfs(start)
        ans.reverse()
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]

