from typing import List
from collections import defaultdict, deque

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        # Build graph: ingredient -> recipes that require it
        adj = defaultdict(list)
        indegree = {}
        for i, recipe in enumerate(recipes):
            indegree[recipe] = len(ingredients[i])
            for ing in ingredients[i]:
                adj[ing].append(recipe)

        q = deque()
        processed = set()
        # Initialize queue with all supplies
        for sup in supplies:
            q.append(sup)
            processed.add(sup)

        result = []
        # Add recipes that need no ingredients (indegree == 0)
        for recipe, deg in indegree.items():
            if deg == 0:
                result.append(recipe)
                q.append(recipe)
                processed.add(recipe)

        # Perform topological BFS
        while q:
            cur = q.popleft()
            for nxt in adj.get(cur, []):
                indegree[nxt] -= 1
                if indegree[nxt] == 0 and nxt not in processed:
                    result.append(nxt)
                    q.append(nxt)
                    processed.add(nxt)

        return result

