from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of all forbidden strings
        trie = {}
        max_len = 0
        for f in forbidden:
            max_len = max(max_len, len(f))
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True  # mark the end of a forbidden pattern

        ans = 0
        left = 0
        n = len(word)

        # Sliding window: expand right pointer and shrink left when a forbidden substring appears
        for right in range(n):
            node = trie
            # Check all suffixes ending at `right` up to max_len characters
            for length in range(1, min(max_len, right - left + 1) + 1):
                ch = word[right - length + 1]
                if ch not in node:
                    break
                node = node[ch]
                if "end" in node:
                    # Found a forbidden substring [right-length+1 .. right]
                    # Move left just after its start so the window stays valid
                    left = max(left, right - length + 2)
            ans = max(ans, right - left + 1)

        return ans

