class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False

        # positions of each character in t
        pos = defaultdict(deque)
        for idx, ch in enumerate(t):
            pos[ch].append(idx)

        # indices of t in the order they appear in s
        a = [pos[ch].popleft() for ch in s]
        n = len(a)

        # BIT to count already placed indices
        bit = BIT(n)

        # offset[d] = minimal allowed i - inv for digit d
        offset = defaultdict(lambda: -1)

        for i, ch in enumerate(s):
            idx = a[i]
            inv = bit.sum(n - 1) - bit.sum(idx)
            bit.update(idx, 1)
            digit = int(ch)
            for d in range(digit - 1, -1, -1):
                if offset[d] >= i - inv:
                    return False
            offset[digit] = i - inv

        return True

