                cycle_s2 = s2_count - prev_s2_count
                cycle_s1 = s1_count - prev_s1_count
                if cycle_s1 > 0:
                    cycles = (n1 - s1_count) // cycle_s1
                    s2_count += cycle_s2 * cycles
                    s1_count += cycle_s1 * cycles
                    if s1_count == n1:
                        break
                state[index] = (s2_count, s1_count)
            else:
                state[index] = (s2_count, s1_count)
