from functools import cache
from typing import List

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Duplicate each topping to allow up to two uses
        topping = toppingCosts * 2

        @cache
        def dfs(i: int, remain: int) -> int:
            """Return sum of a subset of topping[i:] that is closest to `remain`."""
            if i == len(topping) or remain <= 0:
                return 0
            # Skip current topping
            skip = dfs(i + 1, remain)
            # Take current topping
            take = topping[i] + dfs(i + 1, remain - topping[i])
            # Choose result with smallest absolute difference, break ties by smaller sum
            return min(skip, take, key=lambda s: (abs(s - remain), s))

        best = float('inf')
        for bc in baseCosts:
            cur = bc + dfs(0, target - bc)
            best = min(best, cur, key=lambda x: (abs(x - target), x))
        return best

