class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        tree = [[] for _ in range(n)]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        total = sum(nums)

        # Depth‑first search that cuts a subtree when its sum equals the candidate value
        def dfs(u: int, p: int) -> int:
            cur = nums[u]
            for v in tree[u]:
                if v != p:
                    cur += dfs(v, u)
            # If subtree sum equals candidate, treat it as removed (return 0)
            return 0 if cur == cand else cur

        for cand in range(1, total // 2 + 1):
            if total % cand != 0:
                continue
            if dfs(0, -1) == 0:
                return total // cand - 1
        return 0

