from typing import List
from collections import deque
import sys

class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        sys.setrecursionlimit(10**6)
        m, n = len(grid), len(grid[0])
        if grid[0][0] == 0 or grid[m-1][n-1] == 0:
            return False

        # BFS to check if any path exists from start to end
        dq = deque([(0, 0)])
        visited = [[False] * n for _ in range(m)]
        visited[0][0] = True
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        while dq:
            i, j = dq.popleft()
            if i == m - 1 and j == n - 1:
                break
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and not visited[ni][nj]:
                    visited[ni][nj] = True
                    dq.append((ni, nj))
        if not visited[m - 1][n - 1]:
            return False

        # Articulation point detection (Tarjan)
        disc = [[0] * n for _ in range(m)]
        low = [[0] * n for _ in range(m)]
        self.time = 0
        self.found = False

        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        def dfs(i: int, j: int, parent_i: int, parent_j: int) -> None:
            self.time += 1
            disc[i][j] = low[i][j] = self.time
            child_cnt = 0

            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if not (0 <= ni < m and 0 <= nj < n):
                    continue
                if grid[ni][nj] == 0:
                    continue
                if (ni, nj) == (parent_i, parent_j):
                    continue
                if disc[ni][nj] == 0:
                    child_cnt += 1
                    dfs(ni, nj, i, j)
                    low[i][j] = min(low[i][j], low[ni][nj])

                    # Non‑root articulation condition
                    if parent_i != -1:
                        if low[ni][nj] >= disc[i][j]:
                            if not (i == 0 and j == 0) and not (i == m - 1 and j == n - 1):
                                self.found = True
                else:
                    low[i][j] = min(low[i][j], disc[ni][nj])

                if self.found:
                    return

            # Root articulation condition (start cell)
            if parent_i == -1:
                if child_cnt > 1:
                    if not (i == 0 and j == 0) and not (i == m - 1 and j == n - 1):
                        self.found = True

        dfs(0, 0, -1, -1)
        return self.found

