from typing import List

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words:
            return []
        word_len = len(words[0])
        num_words = len(words)
        total_len = word_len * num_words
        if total_len > len(s):
            return []
        word_count = Counter(words)
        res = []
        for offset in range(word_len):
            left = offset
            curr_count = Counter()
            formed = 0
            for right in range(offset, len(s) - total_len + 1, word_len):
                word = s[right:right + word_len]
                if word in word_count:
                    curr_count[word] += 1
                    if curr_count[word] == word_count[word]:
                        formed += 1
                    elif curr_count[word] > word_count[word]:
                        # shrink left side until count matches requirement
                        while curr_count[word] > word_count[word]:
                            left_word = s[left:left + word_len]
                            if left_word in word_count:
                                if curr_count[left_word] == word_count[left_word]:
                                    formed -= 1
                                curr_count[left_word] -= 1
                            left += word_len
                else:
                    # invalid word, reset the window
                    curr_count.clear()
                    formed = 0
                    left = right + word_len
                if formed == num_words:
                    res.append(left)
                    # slide left by one word to find next possible start
                    left_word = s[left:left + word_len]
                    if left_word in word_count:
                        if curr_count[left_word] == word_count[left_word]:
                            formed -= 1
                        curr_count[left_word] -= 1
                    left += word_len
        return res

