class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a reversed trie of all forbidden strings for efficient suffix checks.
        trie = {}
        max_len = 0
        for f in forbidden:
            node = trie
            for ch in reversed(f):
                node = node.setdefault(ch, {})
            node["_end"] = True          # marker for a forbidden string end
            max_len = max(max_len, len(f))

        last = 0            # earliest possible start index for a valid substring ending at current position
        ans = 0
        n = len(word)

        for i in range(n):
            node = trie
            # Check substrings ending at i, scanning backwards up to max_len characters.
            for j in range(i, max(i - max_len, -1), -1):
                ch = word[j]
                if ch not in node:
                    break
                node = node[ch]
                if "_end" in node:
                    # A forbidden string ends at i, starting at j. Move start after it.
                    last = max(last, j + 1)
            # Length of the longest valid substring ending at i.
            cur_len = i - last + 1
            if cur_len > 0:
                ans = max(ans, cur_len)

        return ans

