from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2  # Duplicate each topping to allow up to two uses

        @cache
        def fn(i, x):
            # Base case: if x is negative or we have processed all toppings, return 0.
            if x < 0 or i == len(toppingCosts):
                return 0
            # Option 1: skip the current topping
            skip = fn(i+1, x)
            # Option 2: take the current topping
            take = toppingCosts[i] + fn(i+1, x - toppingCosts[i])
            # Choose the option that minimizes the absolute difference to x, and if tie, the smaller value.
            return min(skip, take, key=lambda y: (abs(y - x), y))

        ans = float('inf')
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # Compare total with target: minimize absolute difference, and then the value (smaller if tie)
            ans = min(ans, total, key=lambda x: (abs(x - target), x))
        return ans

