from typing import List

class Solution:
    def minimumTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        freq = [0] * n
        level = [0] * n
        parent = [0] * n

        def dfs(u: int, d: int, p: int) -> None:
            level[u] = d
            parent[u] = p
            for v in g[u]:
                if v != p:
                    dfs(v, d + 1, u)

        def lca(a: int, b: int) -> int:
            if level[a] > level[b]:
                a, b = b, a
            diff = level[b] - level[a]
            while diff:
                b = parent[b]
                diff -= 1
            if a == b:
                return a
            while a != b:
                a = parent[a]
                b = parent[b]
            return a

        dfs(0, 0, -1)

        for u, v in trips:
            L = lca(u, v)
            x = u
            while x != L:
                freq[x] += 1
                x = parent[x]
            freq[L] += 1
            y = v
            while y != L:
                freq[y] += 1
                y = parent[y]

        total = sum(price[i] * freq[i] for i in range(n))

        def dp(u: int, p: int) -> List[int]:
            not_discount = 0
            discount_saving = (price[u] - price[u] // 2) * freq[u]
            for v in g[u]:
                if v != p:
                    child_not, child_disc = dp(v, u)
                    not_discount += max(child_not, child_disc)
                    discount_saving += child_not
            return [not_discount, discount_saving]

        not_disc_root, disc_root = dp(0, -1)
        max_save = max(not_disc_root, disc_root)
        return total - max_save

