```python
class Solution:
    def dfnumMovStonesII(self, stones: List[int]) -> List[int]:
        stones.sort()
        n = len(stones)
        if n <= 2:
            if n == 1:
                return [0, 0]
            else:
                if stones[1] - stones[0] == 1:
                    return [0, 0]
                else:
                    return [1, 1]
        # Calculate max_moves
        max_moves = min(stones[-1] - stones[1] + 1, stones[-2] - stones[0] + 1) - n
        max_moves = max(0, max_moves)  # Ensure non-negative
        max_moves = min(max_moves, n - 2)  # Cannot exceed n-2
        # Calculate min_moves
        min_moves = 2
        if stones[-1] - stones[0] + 1 == n:
            min_moves = 0
        else:
            for i in range(n - 1):
                if stones[i + 1] - stones[i] == 2:
                    min_moves = 1
                    break
            else:
                if stones[-2] - stones[0] + 1 == n - 1 or stones[-1] - stones[1] + 1 == n - 1:
                    min_moves = 1
                else:
                    min_moves = 2
        return [min_moves, max_moves]
