class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1]  # dp for i = 0 (one element placed)
        for i in range(1, n + 1):
            new_len = i + 1
            newdp = [0] * new_len
            if s[i - 1] == 'D':
                suffix = 0
                for j in range(i - 1, -1, -1):
                    suffix = (suffix + dp[j]) % MOD
                    newdp[j] = suffix
                # newdp[i] remains 0
            else:  # 'I'
                prefix = 0
                for j in range(i + 1):
                    newdp[j] = prefix
                    if j < i:
                        prefix = (prefix + dp[j]) % MOD
            dp = newdp
        return sum(dp) % MOD

