from typing import Optional

class Solution:
    def isSubPath(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:
        if head is None:
            return True
        if root is None:
            return False
        # If current tree node matches the list head, try to match the rest downwards
        if root.val == head.val:
            if self.isSame(head.next, root):
                return True
        # Continue searching in left and right subtrees with the same head list
        return self.isSubPath(head, root.left) or self.isSubPath(head, root.right)

    def isSame(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:
        if head is None:
            return True
        if root is None:
            return False
        if head.val != root.val:
            return False
        # Next list node must follow either left or right child path
        return self.isSame(head.next, root.left) or self.isSame(head.next, root.right)

