    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        if grid[0][0] == 0 or grid[m-1][n-1] == 0:
            return False

        # Initialize DP tables
        dp1 = [[0] * n for _ in range(m)]
        dp2 = [[0] * n for _ in range(m)]

        # Paths from (0,0) to (i,j)
        dp1[0][0] = 1
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                if grid[i][j] == 1:
                    if i > 0:
                        dp1[i][j] += dp1[i-1][j]
                    if j > 0:
                        dp1[i][j] += dp1[i][j-1]

        # If no path exists, return False
        if dp1[m-1][n-1] == 0:
            return False

        # Paths from (i,j) to (m-1,n-1)
        dp2[m-1][n-1] = 1
        for i in range(m-1, -1, -1):
            for j in range(n-1, -1, -1):
                if i == m-1 and j == n-1:
                    continue
                if grid[i][j] == 1:
                    if i < m-1:
                        dp2[i][j] += dp2[i+1][j]
                    if j < n-1:
                        dp2[i][j] += dp2[i][j+1]

        total_paths = dp1[m-1][n-1]

        # Check for critical cells (excluding start/end)
        for i in range(m):
            for j in range(n):
                if (i == 0 and j == 0) or (i == m-1 and j == n-1):
                    continue
                if grid[i][j] == 1:
                    if dp1[i][j] * dp2[i][j] == total_paths:
                        return True

