from typing import List

class Solution:
    def minimumTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        freq = [0] * n
        level = [0] * n
        parent = [0] * n

        def dfs(u: int, l: int, p: int) -> None:
            level[u] = l
            parent[u] = p
            for w in g[u]:
                if w != p:
                    dfs(w, l + 1, u)

        def LCA(a: int, b: int) -> int:
            if level[a] > level[b]:
                a, b = b, a
            d = level[b] - level[a]
            while d:
                b = parent[b]
                d -= 1
            if a == b:
                return a
            while a != b:
                a = parent[a]
                b = parent[b]
            return a

        dfs(0, 0, -1)

        for u, v in trips:
            l = LCA(u, v)
            while u != l:
                freq[u] += 1
                u = parent[u]
            while v != l:
                freq[v] += 1
                v = parent[v]
            freq[l] += 1

        def dp(u: int, p: int) -> List[int]:
            res0 = 0  # u not discounted
            res1 = price[u] // 2 * freq[u]  # u discounted
            for w in g[u]:
                if w == p:
                    continue
                child0, child1 = dp(w, u)
                res0 += max(child0, child1)
                res1 += child0
            return [res0, res1]

        total = sum(freq[i] * price[i] for i in range(n))
        best = max(dp(0, -1))
        return total - best

