                arrange.append(maxi + 1)
                remain -= 1
            else:
                arrange.append(maxi)

        # Split the linked list into parts
        parts = []
        current = head
        for i in range(k):
            if current is None:
                parts.append(None)
                continue
            if arrange[i] == 0:
                parts.append(None)
                continue
            start = current
            for j in range(arrange[i] - 1):
