class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        from functools import lru_cache

        @lru_cache(None)
        def dp(i: int, prev: str, k_left: int, ct: int) -> int:
            if i == n:
                if ct == 0:
                    return 0
                if ct == 1:
                    return 1
                return len(str(ct)) + 1
            if k_left < 0:
                return float('inf')
            # Option 1: delete s[i]
            exc = dp(i + 1, prev, k_left - 1, ct)
            # Option 2: keep s[i]
            if i > 0 and s[i] == prev:
                inc = dp(i + 1, prev, k_left, ct + 1)
            else:
                # cost of the previous run (if any)
                if ct == 0:
                    cost_prev = 0
                elif ct == 1:
                    cost_prev = 1
                else:
                    cost_prev = len(str(ct)) + 1
                inc = cost_prev + dp(i + 1, s[i], k_left, 1)
            return min(inc, exc)

        return dp(0, "", k, 0)

