class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache
        n = len(s)

        def group_len(cnt: int) -> int:
            """Return compressed length of a group of cnt equal characters."""
            if cnt == 0:
                return 0
            # 1 for the character, plus the number of digits of the count (>1)
            return 1 + (0 if cnt == 1 else len(str(cnt)))

        @lru_cache(None)
        def dp(i: int, rem: int, prev: str, cnt: int) -> int:
            if rem < 0:
                return float('inf')
            if i == n:
                return group_len(cnt) if prev else 0
            # Delete current character
            del_cost = dp(i + 1, rem - 1, prev, cnt)
            # Keep current character
            if prev == s[i]:
                keep_cost = dp(i + 1, rem, prev, cnt + 1)
            else:
                keep_cost = group_len(cnt) + dp(i + 1, rem, s[i], 1)
            return min(del_cost, keep_cost)

        return dp(0, k, "", 0)

