from typing import List

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        # dimension check
        for row in lcp:
            if len(row) != n:
                return ''
        # validation: symmetry, bounds, diagonal
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - max(i, j):
                    return ''
                if i == j and lcp[i][j] != n - i:
                    return ''
        # assign pattern letters greedily
        pattern = [None] * n
        next_label = 0
        for i in range(n):
            if pattern[i] is not None:
                continue
            pattern[i] = next_label
            next_label += 1
            for j in range(i + 1, n):
                if lcp[i][j] > 0:
                    if pattern[j] is not None and pattern[j] != pattern[i]:
                        return ''
                    pattern[j] = pattern[i]
        # compute LCP from pattern using DP
        pattern_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if pattern[i] == pattern[j]:
                    if i == n - 1 or j == n - 1:
                        pattern_lcp[i][j] = 1
                    else:
                        pattern_lcp[i][j] = pattern_lcp[i + 1][j + 1] + 1
                else:
                    pattern_lcp[i][j] = 0
        # verify matches original lcp
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != pattern_lcp[i][j]:
                    return ''
        # at most 26 distinct letters
        if max(pattern) >= 26:
            return ''
        return ''.join(chr(ord('a') + x) for x in pattern)

class Solution:
    def smallestString(self, s: str) -> str:
        # Find the first character that is not 'a'
        i = 0
        n = len(s)
        while i < n and s[i] == 'a':
            i += 1
        # If the entire string consists of 'a's, replace the last character with 'z'
        if i == n:
            return s[:-1] + 'z'
        # Convert the contiguous block of non-'a' characters to the previous alphabet letter
        chars = list(s)
        while i < n and s[i] != 'a':
            chars[i] = chr(ord(chars[i]) - 1)
            i += 1
        return ''.join(chars)

