class Solution:
    def dp(self, i, s, prev, k, ct, n, memo):
        if k < 0:
            return float('inf')
        if i == n:
            # cost of final group
            if ct == 0:
                return 0
            elif ct == 1:
                return 1
            else:
                return len(str(ct)) + 1
        key = (i, prev, ct, k)
        if key in memo:
            return memo[key]
        # Option 1: delete s[i]
        exc = self.dp(i + 1, s, prev, k - 1, ct, n, memo)
        # Option 2: keep s[i]
        if s[i] == prev:
            inc = self.dp(i + 1, s, prev, k, ct + 1, n, memo)
        else:
            # close current group and start a new one
            cost = 0
            if ct == 1:
                cost = 1
            elif ct > 1:
                cost = len(str(ct)) + 1
            inc = cost + self.dp(i + 1, s, s[i], k, 1, n, memo)
        res = min(inc, exc)
        memo[key] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, s, '', k, 0, n, {})

