class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character of s2 does not appear in s1, impossible
        if not set(s2).issubset(set(s1)):
            return 0

        # Keep only characters that could appear in s2 (optional optimization)
        s1 = ''.join(ch for ch in s1 if ch in set(s2))

        # Map from position inside s2 after a full copy of s1 to (copies processed, s2 count)
        index_map = {}
        s2_cnt = 0       # total complete s2 subsequences found
        s2_idx = 0       # next character index in s2 we need to match
        i = 0            # copies of s1 processed
        len_s2 = len(s2)

        while i < n1:
            # Scan one copy of s1
            for ch in s1:
                if ch == s2[s2_idx]:
                    s2_idx += 1
                    if s2_idx == len_s2:
                        s2_cnt += 1
                        s2_idx = 0
            i += 1

            # Record state after i copies of s1
            if s2_idx not in index_map:
                index_map[s2_idx] = (i, s2_cnt)
            else:
                # Cycle found: state repeats
                prev_i, prev_cnt = index_map[s2_idx]
                cycle_i = i - prev_i          # how many s1 copies in one cycle
                cycle_cnt = s2_cnt - prev_cnt # how many s2 subsequences per cycle

                # How many full cycles we can apply
                remaining = n1 - prev_i
                full_cycles = remaining // cycle_i
                s2_cnt = prev_cnt + full_cycles * cycle_cnt
                i = prev_i + full_cycles * cycle_i

                # Process the remaining copies one by one
                while i < n1:
                    for ch in s1:
                        if ch == s2[s2_idx]:
                            s2_idx += 1
                            if s2_idx == len_s2:
                                s2_cnt += 1
                                s2_idx = 0
                    i += 1
                break

        return s2_cnt // n2

