from typing import List

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        # Basic validation of the matrix
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - max(i, j):
                    return ''
        # Diagonal must be suffix length
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''

        # Build pattern (0 = 'a', 1 = 'b', ...)
        pattern = [-1] * n
        next_char = 0
        for i in range(n):
            if pattern[i] != -1:
                continue
            pattern[i] = next_char
            next_char += 1
            for j in range(i + 1, n):
                if lcp[i][j] > 0:
                    if pattern[j] != -1 and pattern[j] != pattern[i]:
                        return ''
                    pattern[j] = pattern[i]

        # Compute expected LCP from pattern
        pattern_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if pattern[i] == pattern[j]:
                    if i == n - 1 or j == n - 1:
                        pattern_lcp[i][j] = 1
                    else:
                        pattern_lcp[i][j] = pattern_lcp[i + 1][j + 1] + 1
                else:
                    pattern_lcp[i][j] = 0

        # Verify against given matrix
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != pattern_lcp[i][j]:
                    return ''

        # Must use at most 26 distinct letters
        if max(pattern) >= 26:
            return ''

        return ''.join(chr(ord('a') + idx) for idx in pattern)

