class Solution:
    def smallerNumbersThanCurrent(self, nums: List[int]) -> List[int]:
        count = [0] * 101
        for num in nums:
            count[num] += 1
        # Build prefix sums for cumulative counts
        for i in range(1, 101):
            count[i] += count[i-1]
        # Numbers smaller than current are the cumulative count before the number
        return [0 if num == 0 else count[num-1] for num in nums]

