from typing import List

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        tree = [[] for _ in range(n)]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)
        total = sum(nums)

        def dfs(u: int, parent: int, cand: int) -> int:
            cur = nums[u]
            for v in tree[u]:
                if v == parent:
                    continue
                child = dfs(v, u, cand)
                if child == -1:
                    return -1
                cur += child
            if cur == cand:
                return 0
            if cur > cand:
                return -1
            return cur

        for cand in range(1, total // 2 + 1):
            if total % cand != 0:
                continue
            if dfs(0, -1, cand) == 0:
                return total // cand - 1
        return 0

