class Solution:
    def dp(self, i: int, s: str, prev: str, ct: int, k: int, memo: dict) -> int:
        if k < 0:
            return float('inf')
        if i == len(s):
            # End of string – close the current group
            if ct > 1:
                return len(str(ct)) + 1
            elif ct == 1:
                return 1
            else:
                return 0
        if (i, prev, ct, k) in memo:
            return memo[(i, prev, ct, k)]
        # Delete current character
        exc = self.dp(i + 1, s, prev, ct, k - 1, memo)
        # Keep current character
        if s[i] == prev:
            inc = self.dp(i + 1, s, prev, ct + 1, k, memo)
        else:
            add = 0
            if ct > 1:
                add = len(str(ct)) + 1
            elif ct == 1:
                add = 1
            inc = add + self.dp(i + 1, s, s[i], 1, k, memo)
        ans = min(inc, exc)
        memo[(i, prev, ct, k)] = ans
        return ans

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        return self.dp(0, s, "", 0, k, {})

