class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If s2 contains a character not in s1, it's impossible
        if not set(s2).issubset(set(s1)):
            return 0
        # Track the index in s2 after each s1 block
        recall = {}
        s1_cnt = 0          # number of s1 blocks processed
        s2_cnt = 0          # number of complete s2 occurrences
        idx = 0             # current index in s2 (0 <= idx < len(s2))

        while s1_cnt < n1:
            s1_cnt += 1
            for ch in s1:
                if ch == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        idx = 0
                        s2_cnt += 1
            # Detect a cycle: same idx seen before
            if idx in recall:
                pre_s1, pre_s2 = recall[idx]
                cycle_s1 = s1_cnt - pre_s1
                cycle_s2 = s2_cnt - pre_s2
                remaining = n1 - s1_cnt
                cycles = remaining // cycle_s1
                s2_cnt += cycles * cycle_s2
                s1_cnt += cycles * cycle_s1
                # Process the leftover s1 blocks one by one
                while s1_cnt < n1:
                    s1_cnt += 1
                    for ch in s1:
                        if ch == s2[idx]:
                            idx += 1
                            if idx == len(s2):
                                idx = 0
                                s2_cnt += 1
                break
            else:
                recall[idx] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

