class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int)

        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        # Find a vertex with net out-degree 1 → start of the Eulerian path.
        start = None
        for k, v in degree.items():
            if v == 1:
                start = k
                break
        # If none exists, start from any vertex that appears in the graph.
        if start is None:
            start = next(iter(graph)) if graph else None

        ans = []

        def dfs(u: int) -> None:
            while graph[u]:
                nxt = graph[u].pop()
                dfs(nxt)
            ans.append(u)

        if start is not None:
            dfs(start)

        ans.reverse()
        return [[ans[i], ans[i + 1]] for i in range(len(ans) - 1)]

