import functools

class Solution:
    MOD = 1000000007

    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # Compute total apples
        tot_apples = 0
        for i in range(self.r):
            for j in range(self.c):
                if pizza[i][j] == 'A':
                    tot_apples += 1

        if tot_apples < k:
            return 0

        # Compute 2D prefix sum
        self.psum = [[0] * self.c for _ in range(self.r)]
        for i in range(self.r):
            for j in range(self.c):
                apple = 1 if pizza[i][j] == 'A' else 0
                self.psum[i][j] = apple + (self.psum[i-1][j] if i > 0 else 0) + (self.psum[i][j-1] if j > 0 else 0) - (self.psum[i-1][j-1] if i > 0 and j > 0 else 0)

        # Return the number of ways for k pieces, which requires k-1 cuts
        return self.getWays(0, 0, k-1) % self.MOD

    @functools.lru_cache(maxsize=None)
    def getWays(self, i, j, k):
        # k is the number of cuts left to make
        if k == 0:
            # Check if the current piece has at least one apple
            total_apples = self.psum[self.r-1][self.c-1]
            if i > 0:
                total_apples -= self.psum[i-1][self.c-1]
            if j > 0:
                total_apples -= self.psum[self.r-1][j-1]
            if i > 0 and j > 0:
                total_apples += self.psum[i-1][j-1]
            if total_apples > 0:
                return 1
            else:
                return 0
        else:
            total_ways = 0
            # Horizontal cuts: after each row from i to self.r-2
            for r in range(i, self.r - 1):
                # Check if the piece from (i,j) to (r,self.c-1) has apples
                apples_upper = self.psum[r][self.c-1]
                if i > 0:
                    apples_upper -= self.psum[i-1][self.c-1]
                if j > 0:
                    apples_upper -= self.psum[r][j-1]
                if i > 0 and j > 0:
                    apples_upper += self.psum[i-1][j-1]
                if apples_upper > 0:
                    # Make cut after row r, and recurse on the lower piece from (r+1,j) to (self.r-1,self.c-1) with k-1 cuts
                    total_ways += self.getWays(r+1, j, k-1)

            # Vertical cuts: after each column from j to self.c-2
            for c in range(j, self.c - 1):
                # Check if the piece from (i,j) to (self.r-1,c) has apples
                apples_left = self.psum[self.r-1][c]
                if i > 0:
                    apples_left -= self.psum[i-1][c]
                if j > 0:
                    apples_left -= self.psum[self.r-1][j-1]
                if i > 0 and j > 0:
                    apples_left += self.psum[i-1][j-1]
                if apples_left > 0:
                    # Make cut after column c, and recurse on the right piece from (i,c+1) to (self.r-1,self.c-1) with k-1 cuts
                    total_ways += self.getWays(i, c+1, k-1)

            return total_ways % self.MOD

