from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Duplicate each topping so each can be used at most twice
        toppingCosts = toppingCosts * 2

        @lru_cache(maxsize=None)
        def dfs(i: int, remaining: int) -> int:
            """Return the sum of a subsequence of toppingCosts[i:] closest to remaining."""
            if i == len(toppingCosts) or remaining <= 0:
                return 0
            skip = dfs(i + 1, remaining)
            take = toppingCosts[i] + dfs(i + 1, remaining - toppingCosts[i])
            # Choose the result that brings the total cost nearer to target
            return min(skip, take, key=lambda s: (abs(s - target), s))

        best = float('inf')
        for bc in baseCosts:
            total = bc + dfs(0, target - bc)
            best = min(best, total, key=lambda x: (abs(x - target), x))
        return best

