class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False

        # positions of each character in t
        pos = defaultdict(deque)
        for idx, ch in enumerate(t):
            pos[ch].append(idx)

        # map each character of s to its target index in t
        a = []
        for ch in s:
            a.append(pos[ch].popleft())

        n = len(a)
        bit = BIT(n)

        # for each digit, store the smallest allowed index adjusted by inversions
        ind = defaultdict(lambda: -1)

        for i, ch in enumerate(s):
            target = a[i]
            inv = bit.sum(n - 1) - bit.sum(target)
            bit.update(target, 1)

            digit = int(ch)
            for d in range(digit - 1, -1, -1):
                if ind[d] >= i - inv:
                    return False
            ind[digit] = i - inv

        return True

