from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        rows, cols = len(pizza), len(pizza[0])
        total_apples = sum(row.count('A') for row in pizza)
        if total_apples < k:
            return 0

        # 2D prefix sum: pre[i][j] = number of apples in rectangle (0,0)-(i-1,j-1)
        pre = [[0] * (cols + 1) for _ in range(rows + 1)]
        for i in range(rows):
            row_sum = 0
            for j in range(cols):
                if pizza[i][j] == 'A':
                    row_sum += 1
                pre[i + 1][j + 1] = pre[i][j + 1] + row_sum

        @lru_cache(None)
        def dp(r: int, c: int, cuts: int) -> int:
            # check if remaining pizza has any apple
            if pre[rows][cols] - pre[r][cols] - pre[rows][c] + pre[r][c] == 0:
                return 0
            if cuts == 0:
                return 1

            ans = 0
            # horizontal cuts
            for nr in range(r + 1, rows):
                # top piece (r .. nr-1, c .. cols-1) must contain at least one apple
                if pre[nr][cols] - pre[r][cols] - pre[nr][c] + pre[r][c] > 0:
                    ans += dp(nr, c, cuts - 1)
            # vertical cuts
            for nc in range(c + 1, cols):
                # left piece (r .. rows-1, c .. nc-1) must contain at least one apple
                if pre[rows][nc] - pre[r][nc] - pre[rows][c] + pre[r][c] > 0:
                    ans += dp(r, nc, cuts - 1)
            return ans % (10**9 + 7)

