            if i == len(toppingCosts) or x < 0:
                return 0
            option0 = fn(i+1, x)
            option1 = fn(i+1, x - toppingCosts[i]) + toppingCosts[i]
            option2 = fn(i+2, x - 2*toppingCosts[i]) + 2*toppingCosts[i]
            return min(option0, option1, option2, key=lambda y: (abs(y-x), y))

        best_total = None
        best_diff = float('inf')
        for bc in baseCosts:
            topping_sum = fn(0, target - bc)
            total = bc + topping_sum
            diff = abs(total - target)
            if diff < best_diff or (diff == best_diff and total < best_total):
                best_diff = diff
                best_total = total
        return best_total

