class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character needed by s2 is not present in s1, impossible
        if not set(s2).issubset(set(s1)):
            return 0
        # Keep only characters that can appear in s2 (optimisation)
        s1 = ''.join(ch for ch in s1 if ch in set(s2))
        s2_idx = 0          # current index in s2
        s2_cnt = 0          # number of complete s2 strings matched
        s1_cnt = 0          # number of s1 copies processed
        memo = {}           # maps s2_idx -> (s1_cnt, s2_cnt) before a cycle
        while s1_cnt < n1:
            s1_cnt += 1
            for ch in s1:
                if ch == s2[s2_idx]:
                    s2_idx += 1
                    if s2_idx == len(s2):
                        s2_cnt += 1
                        s2_idx = 0
            # Cycle detection
            if s2_idx in memo:
                prev_s1_cnt, prev_s2_cnt = memo[s2_idx]
                cycle_s1_len = s1_cnt - prev_s1_cnt
                cycle_s2_len = s2_cnt - prev_s2_cnt
                remaining = n1 - s1_cnt
                if cycle_s1_len > 0:
                    full_cycles = remaining // cycle_s1_len
                    s1_cnt += full_cycles * cycle_s1_len
                    s2_cnt += full_cycles * cycle_s2_len
                # Process the rest one by one
                while s1_cnt < n1:
                    s1_cnt += 1
                    for ch in s1:
                        if ch == s2[s2_idx]:
                            s2_idx += 1
                            if s2_idx == len(s2):
                                s2_cnt += 1
                                s2_idx = 0
                break
            else:
                memo[s2_idx] = (s1_cnt, s2_cnt)
        # Number of s2 blocks needed to reach answer
        return s2_cnt // n2

